module digit_product_counter(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [9:0] L,\n    input wire [9:0] R,\n    output reg [31:0] count_1,\n    output reg [31:0] count_2,\n    output reg [31:0] count_3,\n    output reg [31:0] count_4,\n    output reg [31:0] count_5,\n    output reg [31:0] count_6,\n    output reg [31:0] count_7,\n    output reg [31:0] count_8,\n    output reg [31:0] count_9,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] INCREMENT = 2'd2;\n    localparam [1:0] DONE_STATE = 2'd3;\n\n    // Internal registers\n    reg [1:0] state;\n    reg [9:0] current_number;\n    reg [15:0] product;\n    reg [9:0] temp;\n    reg [3:0] digit;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd1000;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            count_1 <= 32'd0;\n            count_2 <= 32'd0;\n            count_3 <= 32'd0;\n            count_4 <= 32'd0;\n            count_5 <= 32'd0;\n            count_6 <= 32'd0;\n            count_7 <= 32'd0;\n            count_8 <= 32'd0;\n            count_9 <= 32'd0;\n            current_number <= 10'd0;\n            product <= 16'd0;\n            temp <= 10'd0;\n            digit <= 4'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        // Initialize counts\n                        count_1 <= 32'd0;\n                        count_2 <= 32'd0;\n                        count_3 <= 32'd0;\n                        count_4 <= 32'd0;\n                        count_5 <= 32'd0;\n                        count_6 <= 32'd0;\n                        count_7 <= 32'd0;\n                        count_8 <= 32'd0;\n                        count_9 <= 32'd0;\n                        current_number <= L;\n                        state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    temp <= current_number;\n                    product <= 16'd1;\n\n                    // Compute digit product\n                    while (temp > 10'd0) begin\n                        digit <= temp % 10'd10;\n                        temp <= temp / 10'd10;\n                        if (digit != 4'd0) begin\n                            product <= product * digit;\n                        end\n                    end\n\n                    // Handle final digit\n                    if (temp != 4'd0) begin\n                        product <= product * temp;\n                    end\n\n                    // Reduce product to single digit\n                    while (product >= 10'd10) begin\n                        temp <= product;\n                        product <= 16'd1;\n                        while (temp > 10'd0) begin\n                            digit <= temp % 10'd10;\n                            temp <= temp / 10'd10;\n                            if (digit != 4'd0) begin\n                                product <= product * digit;\n                            end\n                        end\n                        if (temp != 4'd0) begin\n                            product <= product * temp;\n                        end\n                    end\n\n                    state <= INCREMENT;\n                end\n\n                INCREMENT: begin\n                    // Increment appropriate counter\n                    case (product)\n                        4'd1: count_1 <= count_1 + 32'd1;\n                        4'd2: count_2 <= count_2 + 32'd1;\n                        4'd3: count_3 <= count_3 + 32'd1;\n                        4'd4: count_4 <= count_4 + 32'd1;\n                        4'd5: count_5 <= count_5 + 32'd1;\n                        4'd6: count_6 <= count_6 + 32'd1;\n                        4'd7: count_7 <= count_7 + 32'd1;\n                        4'd8: count_8 <= count_8 + 32'd1;\n                        4'd9: count_9 <= count_9 + 32'd1;\n                        default: ; // Should not happen\n                    endcase\n\n                    // Move to next number\n                    current_number <= current_number + 10'd1;\n\n                    // Check if done\n                    if (current_number > R || cycle_count >= MAX_CYCLES) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        state <= COMPUTE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule